// A client that leaves before its answer: Bun.serve aborts the request's signal, and node:http
// destroys the request and closes the response unfinished. The same package under Bun prints the same.
import http from "node:http";
import net from "node:net";
// a client that sends a request and leaves before the answer
const leave = (port) => new Promise((resolve) => {
  const c = net.connect(port, "127.0.0.1", () => c.write("GET /slow HTTP/1.1\r\nHost: x\r\n\r\n"));
  setTimeout(() => { c.destroy(); resolve(); }, 50);
});
export default async function run() {
  const events = [];
  const server = Bun.serve({
    port: 0,
    async fetch(req) {
      req.signal.addEventListener("abort", () => events.push(`bun abort ${req.signal.reason?.name}`));
      await Bun.sleep(300);
      return new Response("late");
    },
  });
  await leave(server.port);
  await Bun.sleep(400);
  server.stop(true);
  const ns = http.createServer((req, res) => {
    req.on("aborted", () => events.push("node req aborted"));
    req.on("close", () => events.push("node req close"));
    res.on("close", () => events.push(`node res close finished=${res.writableFinished}`));
    setTimeout(() => res.end("late"), 300);
  });
  await new Promise((r) => ns.listen(0, "127.0.0.1", r));
  await leave(ns.address().port);
  await Bun.sleep(400);
  ns.close();
  console.log(events.join("\n"));
}
